/* D05：根据DBC信号表写一个最小手工编码器。不是CAN驱动，不连接实车。
 * 车速start0、小端、unsigned，width8或16；模式start16 length2；雷达start18 length1。
 * profile0：factor0.1 offset0；profile1：0.01/0；profile2：0.1/-10。
 * DBC与cantools是独立核对依据；这份C是教学手写版，不是生成代码。 */
#include <stdio.h>  /* scanf读数据，printf打印；返回值约定见main。 */
#include <stdint.h> /* uint8_t字节；uint32_t无符号中间值。 */
#include <stddef.h> /* size_t非负长度；NULL表示无地址。 */
#include <math.h>   /* isfinite有限数检查；roundf取最近整数，半数远离零。 */

/* 函数声明：参数位置一一对应；返回int是状态，不是车速。
 * factor是每个raw刻度对应的km/h；offset是解码最后加的km/h。 */
int PackSignals(float speed, int mode, int radar, float factor, float offset,
                int width, uint8_t *data, size_t length);
int UnpackSignals(const uint8_t *data, size_t length, float factor,
                  float offset, int width, float *speed);

int main(void) {
    /* [入口] 输入7项：车速 模式 雷达 DBC配置 位宽 修改开关 载荷长度。
     * profile是配置编号，不是CAN字节；width是车速字段位数，不是8字节帧长。 */
    float speed = 0.0f, decoded_speed = 0.0f;
    int mode = 0, radar = 0, profile = 0, width = 16, damage = 0, length_input = 8;
    uint8_t data[8] = {0};
    if (scanf("%f %d %d %d %d %d %d", &speed, &mode, &radar, &profile,
              &width, &damage, &length_input) != 7) {
        printf("status=-3\nvalid=0\n"); return 0;
    }
    if (length_input != 8) { printf("status=-1\nvalid=0\n"); return 0; }
    if (profile < 0 || profile > 2 || (width != 8 && width != 16)
        || damage < 0 || damage > 3) {
        printf("status=-2\nvalid=0\n"); return 0;
    }

    /* [选配置] if/else选因子和偏移。=赋值，==比较，||任一越界就拒绝。
     * 先默认0.1/0；只有profile1、2覆盖默认。f后缀声明float常量。 */
    float factor = 0.1f, offset = 0.0f;
    if (profile == 1) factor = 0.01f;
    else if (profile == 2) offset = -10.0f;
    uint32_t limit = width == 8 ? 255u : 65535u;
    printf("factor=%.2f\noffset=%.1f\nwidth=%d\nraw_limit=%u\n",
           (double)factor, (double)offset, width, (unsigned int)limit);

    /* [调用打包] 暂停main，进入PackSignals；data指向main原数组。
     * length先验证为8，避免把负长度转无符号；函数内还会再次检查。 */
    int status = PackSignals(speed, mode, radar, factor, offset, width, data, 8);
    printf("status=%d\nvalid=%d\n", status, status == 0);
    if (status != 0) return 0;

    /* [发送观察] 低字节先，高字节后；拼回非负raw只是展示。
     * for初值i0，条件i<8，打印后i++；最后一格换行，其余空格。 */
    uint32_t raw = (uint32_t)data[0] | ((uint32_t)data[1] << 8);
    printf("raw=%u\ncontrol=%u\nframe=", (unsigned int)raw, (unsigned int)data[2]);
    for (size_t i = 0; i < 8; i++) {
        printf("%02X%s", (unsigned int)data[i], i == 7 ? "\n" : " ");
    }

    /* [接收修改] 1模式非法，2保留位非法，3接收端误用另一份DBC的比例。
     * damage3不改帧：同样的字节、不同的factor会产生不同物理值。 */
    if (damage == 1) data[2] = (uint8_t)((uint32_t)data[2] | 3u);
    if (damage == 2) data[2] = (uint8_t)((uint32_t)data[2] | 8u);
    float receive_factor = damage == 3 ? 0.01f : factor;
    float receive_offset = damage == 3 ? 0.0f : offset;
    printf("receive_factor=%.2f\nreceive_offset=%.1f\nreceived_control=%u\n",
           (double)receive_factor, (double)receive_offset, (unsigned int)data[2]);
    printf("received_frame=");
    for (size_t i = 0; i < 8; i++) {
        printf("%02X%s", (unsigned int)data[i], i == 7 ? "\n" : " ");
    }

    /* [调用解包] &decoded_speed传地址；只有成功才打印有效新车速。
     * DBC不一致有时仍能过范围检查；decode_status0不证明配置正确。 */
    status = UnpackSignals(data, 8, receive_factor, receive_offset, width, &decoded_speed);
    printf("decode_status=%d\ndecode_valid=%d\n", status, status == 0);
    if (status == 0) printf("decoded_speed=%.2f\n", (double)decoded_speed);
    return 0;
}

int PackSignals(float speed, int mode, int radar, float factor, float offset,
                int width, uint8_t *data, size_t length) {
    /* [打包校验] ||是逻辑或，任一非法条件成立就return-2。
     * speed<0与speed>250是两项完整比较；缺少界限数字是不能编译的语法。 */
    if (data == NULL || length != 8) return -1;
    if (!isfinite(speed) || speed < 0.0f || speed > 250.0f
        || !isfinite(factor) || factor <= 0.0f || !isfinite(offset)
        || mode < 0 || mode > 2 || radar < 0 || radar > 1
        || (width != 8 && width != 16)) return -2;

    /* [反推原始值] physical=raw*factor+offset，反推raw=(physical-offset)/factor。
     * 先检查浮点刻度可表示，再转整数；不能先转uint8_t让高位被丢掉。 */
    uint32_t limit = width == 8 ? 255u : 65535u;
    float scaled = roundf((speed - offset) / factor);
    if (!isfinite(scaled) || scaled < 0.0f || scaled > (float)limit) return -2;
    uint32_t raw = (uint32_t)scaled;

    /* [写载荷] 每次先清全部8格，确保DBC未用位置为0。
     * 位宽8时raw<=255，高字节自动为0；模式位置仍从bit16开始。 */
    for (size_t i = 0; i < 8; i++) data[i] = 0;
    data[0] = (uint8_t)(raw & 255u);
    data[1] = (uint8_t)((raw >> 8) & 255u);
    data[2] = (uint8_t)((uint32_t)mode | ((uint32_t)radar << 2));
    return 0;
}

int UnpackSignals(const uint8_t *data, size_t length, float factor,
                  float offset, int width, float *speed) {
    /* [解包校验] const输入只读；输出指针speed允许写回。
     * DBC说信号在哪，不自动替你实施“模式3非法”和“保留位零”业务约束。 */
    if (data == NULL || speed == NULL || length != 8) return -1;
    if (!isfinite(factor) || factor <= 0.0f || !isfinite(offset)
        || (width != 8 && width != 16) || ((uint32_t)data[2] & 248u) != 0
        || ((uint32_t)data[2] & 3u) > 2u || (width == 8 && data[1] != 0)) return -2;
    for (size_t i = 3; i < 8; i++) if (data[i] != 0) return -2;

    /* [还原车速] 按DBC拼raw，再乘factor，最后加offset。
     * 局部变量physical先计算；合法后才通过*speed写main的decoded_speed。 */
    uint32_t raw = (uint32_t)data[0] | ((uint32_t)data[1] << 8);
    float physical = (float)raw * factor + offset;
    if (!isfinite(physical) || physical < 0.0f || physical > 250.0f) return -2;
    *speed = physical;
    return 0;
}

