/* test_codec.c：独立测试入口，和demo分别生成程序，不把两个main放一起。 */
#include "codec.h"
#ifdef NDEBUG
#error "This test requires enabled assertions. Build codec_tests with -UNDEBUG."
#endif
#include <assert.h> /* assert(条件)：真则继续，假则终止测试并报告位置。 */
#include <math.h>   /* fabsf取float绝对值，用于比较浮点误差。 */
#include <string.h> /* memset给字节缓冲区填值；memcmp比较两块内存。 */
#include <stdio.h>

int main(void) {
    /* [测试标准向量] expected来自独立协议手算，不由被测函数生成。 */
    uint8_t data[8];
    const uint8_t expected[8] = {0xD5, 0x02, 0x05, 0, 0, 0, 0, 0};
    float speed = 99.0f;
    /* 被测调用放在assert外；避免断言关闭时连被测函数也没有执行。 */
    int status = Codec_Encode(72.5f, 1, 1, data, 8);
    assert(status == CODEC_OK);
    assert(memcmp(data, expected, 8) == 0);
    status = Codec_Decode(data, 8, &speed);
    assert(status == CODEC_OK);
    assert(fabsf(speed - 72.5f) < 0.001f);

    /* [测试失败契约] 编码失败必须保持输出缓存；解码失败不能写新车速。 */
    uint8_t saved[8];
    memset(data, 0xA5, 8); memset(saved, 0xA5, 8);
    status = Codec_Encode(-1.0f, 1, 1, data, 8);
    assert(status == CODEC_INVALID);
    assert(memcmp(data, saved, 8) == 0);
    status = Codec_Encode(72.5f, 1, 1, NULL, 8); assert(status == CODEC_INTERFACE);
    status = Codec_Encode(72.5f, 1, 1, data, 7); assert(status == CODEC_INTERFACE);
    status = Codec_Encode(72.5f, 1, 1, data, 8); assert(status == CODEC_OK);
    data[2] = 7; speed = 99.0f;
    status = Codec_Decode(data, 8, &speed);
    assert(status == CODEC_INVALID);
    assert(speed == 99.0f);
    printf("assertions_enabled=1\ntest_passed=1\n");
    return 0; /* CTest看到进程正常退出，记录测试通过。 */
}

