#include "fill.h"
#include <stdio.h> /* scanf读数；printf输出。 */

int main(void) {
    /* [1 初始化8格] 0x10是十六进制16，不是十进制10。下标为0到7。 */
    uint8_t data[8] = {0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17};
    uint8_t before[8] = {0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17};
    int start, count, value, capacity;
    /* [2 先用int接输入] int可保存负数；不能直接读成size_t再期待它保留-1。 */
    if (scanf("%d %d %d %d", &start, &count, &value, &capacity) != 4) return 1;
    int status;
    if (start < 0 || count < 0 || capacity < 0 || capacity > 8) {
        status = -2; /* 输入层拒绝负长度和虚报超过真实8格的容量；不调用库。 */
    } else {
        /* [3 已确认非负，才显式转换类型] (size_t)不做范围检查，它只是转换。 */
        status = Fill_Bytes(data, (size_t)capacity, (size_t)start, (size_t)count, value);
    }
    /* [4 用下标观察结果] 循环顺序是我们打印的顺序，不是证明memset内部写入顺序。 */
    printf("status=%d\nvalid=%d\nfill_byte=%u\n", status, status == 0, (unsigned int)(unsigned char)value);
    printf("before=");
    for (size_t i=0; i<8; ++i) printf("%02X%s", (unsigned int)before[i], i==7 ? "\n" : " ");
    printf("after=");
    for (size_t i=0; i<8; ++i) printf("%02X%s", (unsigned int)data[i], i==7 ? "\n" : " ");
    int changed=0, outside_unchanged=1;
    for (int i=0; i<8; ++i) {
        if (data[i] != before[i]) ++changed; /* 实际不同的格数；不一定等于count。 */
        if ((status != 0 || i < start || i >= start + count) && data[i] != before[i]) outside_unchanged=0;
    }
    printf("changed_count=%d\noutside_unchanged=%d\n", changed, outside_unchanged);
    return 0; /* 演示程序正常完成；业务status=-2不等于进程必须失败退出。 */
}

/* fill.c：唯一实现。这里不知道键盘、网页或CAN，只处理接口约定。 */
#include "fill.h"
#include <string.h> /* memset声明在这里；没有自动的缓冲区容量检查。 */

int Fill_Bytes(uint8_t *data, size_t capacity, size_t start, size_t count, int value) {
    /* [先检查地址] NULL不是可写对象；本接口即使count=0也拒绝NULL。 */
    if (data == NULL) return -1;
    /* [再检查起点] 必须先做这一步，否则capacity-start可能无符号下溢。 */
    if (start > capacity) return -2;
    /* [检查剩余空间] capacity=8,start=2时只剩6字节，count最多为6。
     * 不用start+count比较，避免一般size_t输入相加溢出。 */
    if (count > capacity - start) return -2;
    /* [最后执行] data+2指向data[2]，不是把data[0]的数值加2。
     * memset(data+2,0xA5,3)使下标2/3/4都变成A5，其他位置不变。
     * 标准约定最终覆盖范围，不约定CPU内部按哪个顺序发出写操作。 */
    if (count > 0) memset(data + start, value, count);
    return 0; /* 成功报告状态；它不是memset的返回值，memset本身返回原目标地址。 */
}

/* fill.h：约定能做什么。这里声明接口，函数体只在fill.c里写一次。 */
#ifndef ASW_FILL_H
#define ASW_FILL_H
#include <stdint.h> /* uint8_t：本课每个元素恰好一个8位字节。 */
#include <stddef.h> /* size_t：容量、下标与字节数；无符号，不表达负数。 */

/* 调用者必须保证data确实指向至少capacity个可写字节。
 * capacity是实际可用范围，不是函数自己测出来的。
 * start=起始下标；count=填写字节数；value先转换为unsigned char。
 * 返回0成功，-1空指针，-2范围非法；失败时全部保持原样。
 * count为0且start不超过capacity时成功，不写任何字节。 */
int Fill_Bytes(uint8_t *data, size_t capacity, size_t start, size_t count, int value);
#endif

/* 独立的主机单元测试入口；不是ECU业务入口，文件名不强制叫这个。 */
#include "fill.h"
#include <string.h> /* memcmp只判断被比较字节是否相同。 */
#include <stdio.h>

int main(void) {
    uint8_t data[8] = {0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17};
    const uint8_t expected[8] = {0x10,0x11,0xA5,0xA5,0xA5,0x15,0x16,0x17};
    /* [测试1：完整预期] 预期手写，不再用被测算法来生成预期。
     * 本课用if+return显式检查，不依赖assert/NDEBUG是否启用。 */
    int status=Fill_Bytes(data,8,2,3,0xA5);
    if (status != 0 || memcmp(data,expected,8) != 0) return 1;
    /* [测试2：越界请求应拒绝] 剩1格却要2格，失败后仍与expected一致。 */
    status=Fill_Bytes(data,8,7,2,0);
    if (status != -2 || memcmp(data,expected,8) != 0) return 2;
    /* [测试3：零长度] 起点恰好等于容量，成功但不写内存。 */
    status=Fill_Bytes(data,8,8,0,0);
    if (status != 0 || memcmp(data,expected,8) != 0) return 3;
    /* [测试4：空地址] 本接口约定拒绝，不能调用memset(NULL,... )。 */
    status=Fill_Bytes(NULL,8,0,1,0);
    if (status != -1) return 4;
    /* [测试5：起点超界] 先拒绝，避免后面的无符号减法下溢。 */
    status=Fill_Bytes(data,8,9,0,0);
    if (status != -2 || memcmp(data,expected,8) != 0) return 5;
    /* [测试6：大size_t计数] (size_t)-1是size_t的最大值，应被空间检查拒绝。 */
    status=Fill_Bytes(data,8,0,(size_t)-1,0);
    if (status != -2 || memcmp(data,expected,8) != 0) return 6;
    /* [测试7：转换为字节] 当前8位字节平台上-1转换后为255，即FF。 */
    status=Fill_Bytes(data,8,7,1,-1);
    if (status != 0 || data[7] != 255) return 7;
    printf("checks_passed=7\n");
    return 0; /* 任一检查失败提前非0退出；全部成功才到这里。 */
}

