/* 简单的实际C自测：失败立即返回非0，不依赖NDEBUG/断言开关。 */
int main(void)
{
    AccCalibration cfg = {35.0f, 41.0f};
    AccContext ctx = {ACC_OFF, 0};
    AccOutput out = {0};
    AccInput in = {.driver_enable = 1, .radar_valid = 1, .distance_m = 36.0f};

    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 ||
        out.state != ACC_ACTIVE || out.spacing_alert != 0) return 1;
    in.distance_m = 34.0f;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.spacing_alert != 1) return 2;
    in.distance_m = 40.0f;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.spacing_alert != 1) return 3;
    in.distance_m = 42.0f;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.spacing_alert != 0) return 4;

    in.fault_present = 1;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.state != ACC_FAULT) return 5;
    in.fault_present = 0;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.state != ACC_FAULT) return 6;
    in.driver_enable = 0;
    in.fault_reset = 1;
    if (Acc_Step(&ctx, &in, &cfg, &out) != 0 || out.state != ACC_OFF) return 7;

    in.distance_m = -1.0f;
    if (Acc_Step(&ctx, &in, &cfg, &out) != -2 ||
        out.valid != 0 || ctx.state != ACC_OFF) return 8;

    printf("PASS: hysteresis, fault latch/reset, invalid input\n");
    return 0;
}

