#include "sensor_queue.h"
#include <stdio.h>

/* 动作：0放入一帧，1取出一帧。只有输入队列时才使用frame。 */
typedef enum { ACTION_PUSH = 0, ACTION_POP = 1 } ActionKind;
typedef struct {
    ActionKind kind;
    SensorFrame frame;
} DemoAction;

/* 场景0：入、入、出；最适合第一次追踪。 */
static const DemoAction BASIC[] = {
    {ACTION_PUSH, {72.0f, 45.0f, 100U, 100U}},
    {ACTION_PUSH, {73.0f, 44.0f, 101U, 101U}},
    {.kind = ACTION_POP}
};
/* 场景1：写到下标3，再回到0；满时拒绝第6次放入。 */
static const DemoAction WRAP_FULL[] = {
    {ACTION_PUSH, {70.0f, 50.0f, 1U, 1U}},
    {ACTION_PUSH, {71.0f, 49.0f, 2U, 2U}},
    {.kind = ACTION_POP},
    {ACTION_PUSH, {72.0f, 48.0f, 3U, 3U}},
    {ACTION_PUSH, {73.0f, 47.0f, 4U, 4U}},
    {ACTION_PUSH, {74.0f, 46.0f, 5U, 5U}},
    {ACTION_PUSH, {75.0f, 45.0f, 6U, 6U}},
    {.kind = ACTION_POP},
    {.kind = ACTION_POP},
    {.kind = ACTION_POP},
    {.kind = ACTION_POP}
};
/* 场景2：本帧速度来自周期8、距离来自周期7，拒绝混帧。 */
static const DemoAction MIXED[] = {
    {ACTION_PUSH, {72.0f, 45.0f, 7U, 7U}},
    {ACTION_PUSH, {73.0f, 45.0f, 8U, 7U}},
    {.kind = ACTION_POP},
    {ACTION_PUSH, {73.0f, 44.0f, 8U, 8U}},
    {.kind = ACTION_POP}
};
/* 场景3：空时拒绝Pop，之后重新放入又可读取。 */
static const DemoAction EMPTY[] = {
    {.kind = ACTION_POP},
    {ACTION_PUSH, {60.0f, 55.0f, 4U, 4U}},
    {.kind = ACTION_POP},
    {.kind = ACTION_POP}
};
/* 场景4：非法速度拒绝；其后的正常帧不受影响。 */
static const DemoAction BAD_VALUE[] = {
    {ACTION_PUSH, {-1.0f, 55.0f, 4U, 4U}},
    {ACTION_PUSH, {61.0f, 54.0f, 5U, 5U}},
    {.kind = ACTION_POP}
};

int main(void)
{
    int scenario = 0;
    if (scanf("%d", &scenario) != 1) {
        printf("input_error=1\n");
        return 1;
    }

    /* 这两个量描述本次选中的数组，不是重新复制全部帧。 */
    const DemoAction *actions = NULL;
    size_t action_count = 0U;
    switch (scenario) {
        case 0: actions = BASIC; action_count = sizeof(BASIC) / sizeof(BASIC[0]); break;
        case 1: actions = WRAP_FULL; action_count = sizeof(WRAP_FULL) / sizeof(WRAP_FULL[0]); break;
        case 2: actions = MIXED; action_count = sizeof(MIXED) / sizeof(MIXED[0]); break;
        case 3: actions = EMPTY; action_count = sizeof(EMPTY) / sizeof(EMPTY[0]); break;
        case 4: actions = BAD_VALUE; action_count = sizeof(BAD_VALUE) / sizeof(BAD_VALUE[0]); break;
        default: printf("input_error=2\n"); return 1;
    }

    /* 只有一个队列，放在for外；每次操作后位置、数量都保留。 */
    FrameQueue queue = {0};
    printf("scenario=%d actions=%zu capacity=%u\n",
           scenario, action_count, (unsigned)QUEUE_CAPACITY);

    for (size_t i = 0U; i < action_count; ++i) {
        const DemoAction *action = &actions[i];
        int status = 0;
        SensorFrame received = {0}; /* 本轮输出对象 */
        if (action->kind == ACTION_PUSH) {
            status = Queue_Push(&queue, &action->frame);
            printf("step=%zu op=push cycle=%u/%u status=%d head=%zu tail=%zu count=%zu\n",
                   i, (unsigned)action->frame.speed_cycle,
                   (unsigned)action->frame.distance_cycle, status,
                   queue.head, queue.tail, queue.count);
        } else {
            status = Queue_Pop(&queue, &received);
            printf("step=%zu op=pop status=%d head=%zu tail=%zu count=%zu",
                   i, status, queue.head, queue.tail, queue.count);
            if (status == 0) {
                printf(" cycle=%u speed=%.1f distance=%.1f",
                       (unsigned)received.speed_cycle,
                       (double)received.speed_kmh, (double)received.distance_m);
            }
            printf("\n");
        }
    }
    return 0;
}

#ifndef ASW_SENSOR_QUEUE_H
#define ASW_SENSOR_QUEUE_H
#include <stddef.h>
#include <stdint.h>
#define QUEUE_CAPACITY 4u

/* 同一逻辑帧：两个物理量与它们各自所属的采样周期标识。 */
typedef struct {
    float speed_kmh;
    float distance_m;
    uint32_t speed_cycle;
    uint32_t distance_cycle;
} SensorFrame;

/* 保存4份完整帧；head读取位置，tail下次写入位置，count当前占用数。 */
typedef struct {
    SensorFrame slots[QUEUE_CAPACITY];
    size_t head;
    size_t tail;
    size_t count;
} FrameQueue;

/* 返回：0成功，-1指针错误，-2输入值或采样周期不一致，-3满/空。 */
int Queue_Push(FrameQueue *queue, const SensorFrame *frame);
int Queue_Pop(FrameQueue *queue, SensorFrame *out);

#endif

#include "sensor_queue.h"
#include <math.h>
#include <stddef.h>

/* 只负责处理一个完整输入帧，不直接读取CAN，不启动线程。 */
int Queue_Push(FrameQueue *queue, const SensorFrame *frame)
{
    if (queue == NULL || frame == NULL) return -1;

    /* 先拒绝无效数据，不修改队列。 */
    if (!isfinite(frame->speed_kmh) || !isfinite(frame->distance_m) ||
        frame->speed_kmh < 0.0f || frame->speed_kmh > 250.0f ||
        frame->distance_m < 0.0f || frame->distance_m > 500.0f)
        return -2;

    /* 本教学示例要求速度和距离来自同一个采样周期。 */
    if (frame->speed_cycle != frame->distance_cycle) return -2;

    if (queue->count == QUEUE_CAPACITY) return -3;

    /* 整体复制一帧：slots中的元素从此独立于调用者的frame对象。 */
    queue->slots[queue->tail] = *frame;
    queue->tail = (queue->tail + 1U) % QUEUE_CAPACITY;
    ++queue->count;
    return 0;
}

int Queue_Pop(FrameQueue *queue, SensorFrame *out)
{
    if (queue == NULL || out == NULL) return -1;
    if (queue->count == 0U) return -3;

    /* 先取完整帧再改变head；输出是调用者提供的另一个结构体。 */
    SensorFrame draft = queue->slots[queue->head];
    *out = draft;
    queue->head = (queue->head + 1U) % QUEUE_CAPACITY;
    --queue->count;
    return 0;
}

#include "sensor_queue.h"
#include <stdio.h>

/* 使用具体返回码而不是只靠assert；测试和demo各有自己的main。 */
int main(void)
{
    FrameQueue q = {0};
    SensorFrame out = {0};
    SensorFrame a = {72.0f, 45.0f, 1U, 1U};
    SensorFrame b = {73.0f, 44.0f, 2U, 2U};
    SensorFrame c = {74.0f, 43.0f, 3U, 3U};
    SensorFrame d = {75.0f, 42.0f, 4U, 4U};
    SensorFrame e = {76.0f, 41.0f, 5U, 5U};
    SensorFrame f = {77.0f, 40.0f, 6U, 6U};
    SensorFrame mixed = {80.0f, 40.0f, 9U, 8U};

    if (Queue_Pop(&q, &out) != -3 || q.count != 0U) return 1;
    if (Queue_Push(&q, &a) != 0 || Queue_Push(&q, &b) != 0) return 2;
    if (Queue_Pop(&q, &out) != 0 || out.speed_cycle != 1U) return 3;
    if (Queue_Push(&q, &c) != 0 || Queue_Push(&q, &d) != 0 ||
        Queue_Push(&q, &e) != 0) return 4;
    if (q.head != 1U || q.tail != 1U || q.count != 4U) return 5;
    if (Queue_Push(&q, &f) != -3 || q.count != 4U) return 6;

    for (uint32_t id = 2U; id <= 5U; ++id) {
        if (Queue_Pop(&q, &out) != 0 || out.speed_cycle != id) return 7;
    }
    if (q.count != 0U || Queue_Pop(&q, &out) != -3) return 8;
    if (Queue_Push(&q, &mixed) != -2 || q.count != 0U) return 9;
    if (Queue_Push(&q, NULL) != -1 || Queue_Pop(NULL, &out) != -1) return 10;
    a.speed_kmh = -1.0f;
    if (Queue_Push(&q, &a) != -2 || q.count != 0U) return 11;

    printf("PASS: empty, FIFO, wrap, full, mixed-cycle, bounds, NULL\n");
    return 0;
}

